import "./App.css";
import { useState } from "react";
import Logo from "./Logo";
import Form from "./Form";

function App() {
  const [items, setItems] = useState([]);
  function handleAddItem(newItem) {
    setItems((prevItems) => [...prevItems, newItem]);
  }

  return (
    <div className="app">
      <Logo />
      <Form onAddingItem={handleAddItem} />
    </div>
  );
}

export default App;
